function consumerEventLabel(v){return ({ORDER_CREATED:'订单已创建',PAYMENT_AUTHORIZED:'支付已授权',PAYMENT_CAPTURED:'支付已完成',ORDER_CONFIRMED:'预订已确认',SUPPLIER_CONFIRMED:'供应商已确认',ORDER_CANCELLED:'订单已取消',REFUND_COMPLETED:'退款已完成',REFUND_REQUESTED:'退款申请已提交'})[v]||CONSUMER_STATE_LABELS[v]||'订单记录已更新'}
function consumerLabel(v){const k=String(v??'');return CONSUMER_STATE_LABELS[k]||({TRUE:'是',FALSE:'否'}[k.toUpperCase()])||'待确认'}
function roomDisplay(o){return o?.room_type_name||o?.room_name||o?.name||'已选房型'}
function sourceDisplay(v){return consumerLabel(v)||'授权来源'}
function safe(v,f='—'){if(v===null||v===undefined||v==='')return uxEsc(f);if(typeof v==='object')return uxEsc(f);return uxEsc(v)}
function zhDate(v){if(!v)return '待确认';try{return new Date(v+'T00:00:00').toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'})}catch{return safe(v)}}
function minutesLabel(v){const n=Number(v||0);if(!n)return '时长待确认';const h=Math.floor(n/60),m=n%60;return h?`${h}小时${m?m+'分':''}`:`${m}分钟`}
function roomFacts(o={}){const a=o.room_attributes||o.attributes||{};const occ=o.occupancy||{};const beds=o.bed_configurations||[];const bits=[];if(a.area_sqm||a.area)bits.push(`${a.area_sqm||a.area}㎡`);if(a.window_type)bits.push(a.window_type==='NONE'?'无窗':'有窗');if(a.view)bits.push(a.view);if(beds.length){const b=beds[0]||{};bits.push(`${b.count||1}张${b.width_m?b.width_m+'m':''}${b.type_zh||b.type||'床'}`)}if(occ.max_guests||occ.max_occupancy)bits.push(`最多${occ.max_guests||occ.max_occupancy}人`);return bits}
function offerBenefits(o={}){const out=[];if(o.official_direct)out.push('GO 官方直连');if(o.meal_plan&&o.meal_plan!=='NONE')out.push(safe(o.meal_plan));if(o.refundable)out.push('可取消');else out.push('限制取消');const e=o.entitlements||o.official_benefits||[];(Array.isArray(e)?e:[]).slice(0,3).forEach(x=>out.push(safe(x?.name_zh||x?.name||x)));return [...new Set(out.filter(Boolean))]}
function bindVerticalTabs(){document.querySelectorAll('[data-vertical]').forEach(b=>b.onclick=()=>{const v=b.dataset.vertical;if(v==='HOTEL')showHotelSearch();else if(v==='FLIGHT')showFlightSearch();else if(v==='RAIL')showRailSearch();else if(v==='RIDE')showRideSearch();else if(v==='RENTAL')showRentalSearch();else if(v==='ATTRACTION')showAttractionSearch();})}
function consumerEmpty(title,desc,action='',id=''){return `<section class="card consumer-empty"><h3>${title}</h3><p class="muted">${desc}</p>${action?`<button class="btn primary" ${id?`id="${id}"`:''}>${action}</button>`:''}</section>`}
function cookie(name){return document.cookie.split('; ').find(x=>x.startsWith(name+'='))?.split('=')[1]||''}
let consumerRefreshPending = null;
async function consumerRaw(path, opts = {}) {
  const method = (opts.method || 'GET').toUpperCase();
  const headers = {'Content-Type': 'application/json', ...(opts.headers || {}), 'X-GO-Session': 'consumer'};
  if (!['GET', 'HEAD', 'OPTIONS'].includes(method) && cookie('go_consumer_csrf')) {
    headers['X-CSRF-Token'] = decodeURIComponent(cookie('go_consumer_csrf'));
  }
  const response = await fetch(path, {...opts, method, credentials: 'same-origin', headers});
  let body = {}; try { body = await response.json(); } catch {}
  if (!response.ok) {
    const detail = body.detail || body.error?.code || `HTTP ${response.status}`;
    const error = new Error(typeof detail === 'string' ? detail : (detail?.message || detail?.code || '请求未完成'));
    error.status = response.status; throw error;
  }
  return body.data;
}
async function api(path, opts = {}) {
  const csrfAtStart = cookie('go_consumer_csrf');
  try { return await consumerRaw(path, opts); }
  catch (error) {
    if (error.status !== 401 || (path.startsWith('/v1/consumer/auth/') && path !== '/v1/consumer/auth/logout') || !csrfAtStart) throw error;
    if (cookie('go_consumer_csrf') === csrfAtStart) {
      consumerRefreshPending ||= consumerRaw('/v1/consumer/auth/refresh', {method: 'POST'}).finally(() => { consumerRefreshPending = null; });
      await consumerRefreshPending;
    }
    const method = (opts.method || 'GET').toUpperCase();
    if (!['GET', 'HEAD', 'OPTIONS'].includes(method) && path !== '/v1/consumer/auth/logout' && !opts.headers?.['Idempotency-Key']) {
      throw new Error('登录已续期，请核对当前状态后重试。');
    }
    return consumerRaw(path, opts);
  }
}
function toast(m){const x=document.createElement('div');x.className='toast';x.setAttribute('role','status');x.setAttribute('aria-live','polite');x.textContent=m;document.body.appendChild(x);setTimeout(()=>x.remove(),2400)}
function uxEsc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function uxCloseSheet(){document.querySelector('.ux-sheet-backdrop')?.remove()}
function uxSheet({title,description='',fields=[],summary='',confirmLabel='确认',cancelLabel='取消',danger=false,onConfirm}){uxCloseSheet();const wrap=document.createElement('div');wrap.className='ux-sheet-backdrop';wrap.innerHTML=`<section class="ux-sheet" role="dialog" aria-modal="true" aria-labelledby="uxSheetTitle"><div class="ux-sheet-handle"></div><h2 id="uxSheetTitle">${uxEsc(title)}</h2>${description?`<p class="muted">${uxEsc(description)}</p>`:''}<div class="ux-sheet-fields">${fields.map(f=>`<div class="field"><label for="${uxEsc(f.id)}">${uxEsc(f.label)}</label><input id="${uxEsc(f.id)}" type="${uxEsc(f.type||'text')}" value="${uxEsc(f.value||'')}" placeholder="${uxEsc(f.placeholder||'')}" ${f.required===false?'':'required'}></div>`).join('')}</div>${summary?`<div class="ux-sheet-summary">${summary}</div>`:''}<div class="ux-sheet-actions"><button class="btn ghost" id="uxCancel">${uxEsc(cancelLabel)}</button><button class="btn ${danger?'danger':'primary'}" id="uxConfirm">${uxEsc(confirmLabel)}</button></div></section>`;document.body.appendChild(wrap);const first=wrap.querySelector('input');setTimeout(()=>first?.focus(),0);wrap.querySelector('#uxCancel').onclick=uxCloseSheet;wrap.onclick=e=>{if(e.target===wrap)uxCloseSheet()};wrap.querySelector('#uxConfirm').onclick=async()=>{const values={};for(const f of fields){const el=wrap.querySelector('#'+CSS.escape(f.id));if(f.required!==false&&!el.value){el.focus();toast(`请填写${f.label}`);return}values[f.id]=el.value}const btn=wrap.querySelector('#uxConfirm');btn.disabled=true;btn.textContent='处理中…';try{await onConfirm?.(values);uxCloseSheet()}catch(e){toast(e.message);btn.disabled=false;btn.textContent=confirmLabel}}}
function uxConfirm({title,description='',summary='',confirmLabel='确认',danger=false,onConfirm}){return uxSheet({title,description,summary,fields:[],confirmLabel,danger,onConfirm})}

function consumerHeader(showHomeTagline=false){return `<header class="go-header shared-consumer-header"><div class="go-header-inner"><picture class="go-v14-lockup"><source media="(max-width:479px)" srcset="/go-app/assets/go-compact-lockup-v14.svg?v=20260909-depth28"><img class="go-main-lockup" src="/go-app/assets/${showHomeTagline?'go-compact-lockup-v14.svg':'go-main-lockup-v14.svg'}?v=20260909-depth28" alt="${showHomeTagline?'GO AI DIRECT+':'GO AI DIRECT+ 发现全世界 直接向官方预订'}"></picture><div class="go-header-actions">${!state.me?'<button class="btn ghost" id="consumerSignupEntry" type="button">注册</button>':''}<button class="go-icon-button" id="messagesBtn" aria-label="消息"><img src="/go-app/assets/icons/bell.svg" alt=""><span class="go-notice-dot"></span></button><button class="go-icon-button" id="accountBtn" aria-label="我的"><img src="/go-app/assets/icons/profile.svg" alt=""></button></div></div>${showHomeTagline?'<p class="go-home-tagline">发现全世界，直接向官方预订</p>':''}</header>`}
function consumerNav(tab='home'){const items=[['home','home.svg','首页'],['trips','trips.svg','行程'],['favorite','favorite.svg','收藏'],['messages','messages.svg','消息'],['profile','profile.svg','我的']];return `<nav class="go-bottom-nav shared-consumer-nav" aria-label="主要导航">${items.map(([key,icon,label])=>`<button data-nav="${key}" class="${tab===key?'active':''}" aria-current="${tab===key?'page':'false'}"><img src="/go-app/assets/icons/${icon}" alt=""><span>${label}</span></button>`).join('')}</nav>`}
function shell(body,tab='home'){return `<div class="shell home-shell">${consumerHeader()}<main class="content home-content shared-consumer-content">${body}</main>${consumerNav(tab)}</div>`}
function bindNav(){const signup=$('#consumerSignupEntry');if(signup)signup.onclick=showConsumerRegister;const ab=$('#accountBtn');if(ab)ab.onclick=()=>state.me?showAccount():showAuth();const mb=$('#messagesBtn');if(mb)mb.onclick=showMessages;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=async()=>{const n=b.dataset.nav;if(n==='home')bootstrapConsumer().finally(showHome);if(n==='trips')await showUnifiedTrips();if(n==='favorite')showFavorites();if(n==='messages')showMessages();if(n==='profile')state.me?showAccount():showAuth();})}

function showAuth(){setVerticalVIMode(false);document.querySelector('#app').innerHTML=shell(`<h1 class="screen-title">登录 GO</h1><div class="sub">使用 GO ID 管理您的全部旅行订单</div><form class="card" id="consumerLogin"><div class="field"><label for="email">邮箱</label><input id="email" type="email" autocomplete="username" required></div><div class="field"><label for="pwd">密码</label><input id="pwd" type="password" autocomplete="current-password" required></div><p id="consumerLoginError" role="alert"></p><button class="btn primary" id="login" type="submit">登录</button><button class="btn ghost" id="register" type="button">注册新 GO ID</button></form>`,'home');bindNav();$('#consumerLogin').onsubmit=async e=>{e.preventDefault();const button=$('#login');if(button.disabled)return;button.disabled=true;button.textContent='正在登录…';$('#consumerLoginError').textContent='';try{await api('/v1/consumer/auth/login',{method:'POST',body:JSON.stringify({email:$('#email').value.trim(),password:$('#pwd').value})});await bootstrapConsumer();if(!state.me)throw new Error('登录状态尚未确认，请重试。');showHome()}catch(error){$('#consumerLoginError').textContent=error.message==='INVALID_CREDENTIALS'?'邮箱或密码不正确，请重新输入。':error.message;button.disabled=false;button.textContent='登录'}};$('#register').onclick=showConsumerRegister}
async function logoutConsumer(){try{await api('/v1/consumer/auth/logout',{method:'POST'});}catch(error){toast('退出未完成，请检查连接后重试。');return}for(const key of Object.keys(state))state[key]=Array.isArray(state[key])?[]:null;state.screen='home';showHome()}

async function showConsumerRegister(){
 setVerticalVIMode(false);
 document.querySelector('#app').innerHTML=shell(`<h1 class="screen-title">注册 GO ID</h1><p class="sub">注册面向全国用户；条款正式确认后可提交。使用邮箱和密码登录，手机号选填。</p><form class="card" id="consumerRegister"><div class="field"><label for="regName">姓名</label><input id="regName" autocomplete="name" maxlength="100" required></div><div class="field"><label for="regEmail">邮箱</label><input id="regEmail" type="email" autocomplete="email" maxlength="254" required></div><div class="field"><label for="regPhone">手机号（选填，不作为已验证身份）</label><input id="regPhone" type="tel" autocomplete="tel" maxlength="32"></div><div class="field"><label for="regPwd">设置密码（至少 10 位）</label><input id="regPwd" type="password" minlength="10" maxlength="128" autocomplete="new-password" required></div><section id="registrationDocuments" aria-label="注册条款全文"></section><label><input id="regTerms" type="checkbox" required disabled>我同意 GO 用户服务条款、隐私政策及个人旅行信息库规则。旅行资料仅在我授权的旅行用途下释放。</label><p id="consumerRegisterError" role="alert"></p><button class="btn primary" id="doRegister" type="submit" disabled>正在获取注册规则…</button><button class="btn ghost" id="backLogin" type="button">返回登录</button></form>`,'home');
 bindNav();const form=$('#consumerRegister'),button=$('#doRegister'),errorBox=$('#consumerRegisterError');
 $('#backLogin').onclick=showAuth;
 let terms;
 form.onsubmit=async event=>{
  event.preventDefault();if(button.disabled||!terms?.enabled||!form.isConnected||!form.reportValidity())return;
  if(!$('#regTerms').checked){errorBox.textContent='请先阅读并同意注册条款';return}
  button.disabled=true;button.textContent='正在注册…';errorBox.textContent='';
  try{
   await api('/v1/consumer/auth/register',{method:'POST',body:JSON.stringify({email:$('#regEmail').value.trim(),password:$('#regPwd').value,display_name:$('#regName').value.trim(),phone:$('#regPhone').value.trim()||null,accepted_terms:true,term_versions:terms.versions,term_hashes:terms.hashes})});
   await bootstrapConsumer();if(!form.isConnected)return;
   if(!state.me)throw new Error('账号已创建，但登录状态未确认，请返回登录。');
   showAccount(true);
  }catch(error){if(!form.isConnected)return;errorBox.textContent=({EMAIL_ALREADY_REGISTERED:'此邮箱已注册，请返回登录。',CONSUMER_TERMS_VERSION_MISMATCH:'注册条款已更新，请重新进入注册页面。'})[error.message]||error.message;button.disabled=true;$('#regTerms').checked=false;$('#regTerms').disabled=true;button.textContent='请重新进入注册页面'}
 };
 try{const options=await api('/v1/consumer/auth/registration');if(!form.isConnected)return;terms=await GORegistrationTerms.mount({container:$('#registrationDocuments'),policy:options,request:api,isCurrent:()=>form.isConnected});if(!form.isConnected||!terms)return;$('#regTerms').checked=false;$('#regTerms').disabled=!terms.enabled;button.disabled=!terms.enabled;button.textContent=terms.enabled?'注册 GO ID':'条款待确认，暂不可注册'}catch(error){if(form.isConnected){errorBox.textContent='无法获取注册规则，请稍后重新进入。';button.textContent='注册暂不可用'}}
}

async function bootstrapConsumer(){try{state.me=await api('/v1/consumer/me');state.wallet=await api('/v1/consumer/wallet');try{state.vaultCompleteness=await api('/v1/consumer/profile/completeness')}catch{state.vaultCompleteness=null}}catch{state.me=null;state.wallet=null;state.vaultCompleteness=null}}
function showAccount(newRegistration=false){setVerticalVIMode(false);const c=state.vaultCompleteness||{};document.querySelector('#app').innerHTML=shell(`<h1 class="screen-title">我的 GO ID</h1>${newRegistration?'<section class="card"><h3>下一步：一键建立我的旅行信息库</h3><p class="muted">先建立本人旅行资料底座，以后酒店、机票、铁路、用车、租车和门票可在您授权后复用，避免反复填写。</p><button class="btn primary" id="vaultBootstrapTop">一键建立</button></section>':''}<section class="card"><div class="kv"><span>GO ID</span><b>${state.me?.go_id||'—'}</b></div><div class="kv"><span>邮箱</span><span>${state.me?.email||'—'}</span></div><div class="kv"><span>旅行信息库</span><b>${c.completeness_bps!=null?Math.round(c.completeness_bps/100)+'%':'尚未建立'}</b></div><div class="kv"><span>数据使用</span><span>默认不向供应商共享；敏感资料必须取得用途授权</span></div><button class="btn ghost" id="vaultBootstrap" style="margin-top:8px">${c.traveler_count?'完善我的旅行信息库':'一键建立我的旅行信息库'}</button><div class="kv"><span>支付安全</span><span>支付凭据由各渠道托管，GO 不采集卡号或 CVC</span></div><button class="btn ghost" id="logout" style="margin-top:8px">退出登录</button></section>`,'home');bindNav();const build=async()=>{try{const r=await api('/v1/consumer/profile/vault/bootstrap',{method:'POST',body:JSON.stringify({full_name:state.me?.display_name,phone:state.me?.phone})});state.vaultCompleteness=r.completeness;toast('旅行信息库已建立');showAccount()}catch(e){toast(e.message)}};if($('#vaultBootstrap'))$('#vaultBootstrap').onclick=build;if($('#vaultBootstrapTop'))$('#vaultBootstrapTop').onclick=build;$('#logout').onclick=logoutConsumer}
