function renderPay(){const o=state.order;$('#app').innerHTML=shell(`<button class="back" id="back">← 订单核对</button><h1 class="screen-title">选择支付渠道</h1><div class="sub">渠道切换必须由你确认；状态未知时不会重复扣款</div><section class="card"><div class="row"><div><b>应付总额</b><div class="price">${money(o.total_amount_minor,o.currency)}</div></div><span class="status">预授权</span></div><div class="field" style="margin:18px 0"><label for="payChannel">支付渠道</label><select id="payChannel"><option value="ALIPAY">支付宝</option><option value="WECHAT_PAY">微信支付</option><option value="UNIONPAY_QUICKPASS">银联云闪付</option><option value="VISA">Visa</option><option value="MASTERCARD">Mastercard</option><option value="APPLE_PAY">Apple Pay</option><option value="GOOGLE_PAY">Google Pay</option></select></div><button class="btn primary" id="pay">继续到渠道</button></section>`,'search');bindNav();$('#back').onclick=renderReviewOrder;$('#pay').onclick=checkout}
