function renderReview(){const r=state.review;const issues=[['CHECKIN_WAIT_TOO_LONG','入住等待'],['ROOM_NOT_CLEAN','房间清洁'],['SERVICE_SLOW','服务响应'],['NOISE_SLEEP','睡眠/噪音'],['BENEFIT_NOT_HONORED','权益未兑现'],['SERIOUS_HYGIENE','严重卫生'],['SAFETY','安全问题'],['ABNORMAL_CHARGE','异常收费']];$('#app').innerHTML=shell(`<h1 class="screen-title">上次入住怎么样？</h1><div class="sub">像 Uber 一样快速完成；低分需要说明具体发生了什么。</div><section class="card"><div class="stars">${[1,2,3,4,5].map(n=>`<button data-star="${n}" class="${state.stars>=n?'on':''}">★</button>`).join('')}</div><div id="issues" style="display:${state.stars&&state.stars<=3?'block':'none'}"><h3>发生了什么？</h3><div class="issue-grid">${issues.map(x=>`<button class="issue ${state.tags.includes(x[0])?'selected':''}" data-tag="${x[0]}">${x[1]}</button>`).join('')}</div><button class="btn primary" id="submitLow" style="margin-top:14px">提交评价</button></div><div class="tiny" style="text-align:center;margin-top:14px">1–5星是你的原始表达；GO Truth 正常公开体验分仍为3.0–5.0，严重问题独立进入风险事件。</div></section>`,'review');bindNav();document.querySelectorAll('[data-star]').forEach(b=>b.onclick=()=>submitStar(+b.dataset.star));document.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>{const t=b.dataset.tag;state.tags=state.tags.includes(t)?state.tags.filter(x=>x!==t):[...state.tags,t].slice(0,5);renderReview()});if($('#submitLow'))$('#submitLow').onclick=submitLow}
