function renderFlightOrder(){const o=state.flightOrder||{},i=(o.itinerary||[])[0]||{};$('#app').innerHTML=shell(`<h1 class="screen-title">机票订单</h1><section class="card"><div class="kv"><span>状态</span><b>${consumerLabel(o.status)}</b></div><div class="kv"><span>行程</span><b>${safe(i.origin)} → ${safe(i.destination)}</b></div><div class="kv"><span>PNR</span><span>${safe(o.pnr)}</span></div><div class="kv"><span>票号</span><span>${safe((o.ticket_numbers||[]).join(' / '))}</span></div><p class="muted">RC20 Staging 工程交易链；不代表真实航司生产出票或生产支付已启用。</p></section><section class="card"><button class="btn ghost" id="fchg" ${o.status!=='TICKETED'?'disabled':''}>改签</button><button class="btn danger" id="fref" ${o.status!=='TICKETED'?'disabled':''}>退票</button><button class="btn ghost" id="ftrips">GO Trips</button></section><section class="card"><h3>证据链</h3>${evHtml(o.evidence)}</section>`,'trips');bindNav();$('#ftrips').onclick=showUnifiedTrips;$('#fchg').onclick=flightChange;$('#fref').onclick=flightRefund}
async function flightReload(){state.flightOrder=await api(`/v1/flights/orders/${state.flightOrder.order_id}`);renderFlightOrder()}
function flightChange(){const id=state.flightOrder.order_id;return window.GOFlightChanges.open(state.flightOrder,api,flightReload,()=>state.flightOrder?.order_id===id)}
async function flightRefund(){try{const q=await api(`/v1/flights/orders/${state.flightOrder.order_id}/refund-quote`);uxConfirm({title:'申请机票退款',summary:`<div class="kv"><span>预计退款</span><b>${money(q.refund_amount_minor,q.currency)}</b></div>`,confirmLabel:'确认退款',danger:true,onConfirm:async()=>{await api(`/v1/flights/orders/${state.flightOrder.order_id}/refund`,{method:'POST'});await flightReload()}})}catch(e){toast(e.message)}}

function showRailSearch(){setVerticalVIMode(true);state.screen='rail';$('#app').innerHTML=shell(`<section class="go-page-head"><button class="go-back" id="railBack" aria-label="返回">‹</button><div><span>火车票</span><h1>搜索车次</h1></div></section><section class="go-form-card"><div class="route-row"><div class="field"><label for="ro">出发站</label><input id="ro" placeholder="上海 / SHA"></div><span>→</span><div class="field"><label for="rd">到达站</label><input id="rd" placeholder="杭州 / HZH"></div></div><div class="field wide"><label for="rdate">出发日期</label><input id="rdate" type="date"></div><button class="btn primary" id="rgo">查询车次</button></section>`,'home');bindNav();$('#railBack').onclick=showHome;$('#rgo').onclick=railSearch}
async function railSearch(){try{const b={origin_station:$('#ro').value||'SHA',destination_station:$('#rd').value||'HZH',travel_date:$('#rdate').value,currency:'CNY'};if(!b.travel_date){toast('请选择日期');return}state.railCriteria=b;const d=await api('/v1/rail/search',{method:'POST',body:JSON.stringify(b)});state.railSearch=d.items||[];$('#app').innerHTML=shell(`<h1 class="screen-title">车次结果</h1>${state.railSearch.map(x=>`<section class="card" data-rail="${x.offer_id}"><div class="row"><h3>${safe(x.train_no)} · ${consumerLabel(x.seat_class)}</h3><b>${money(x.total_amount_minor,x.currency)} / 成人</b></div><div class="kv"><span>${safe(x.departure_time)} → ${safe(x.arrival_time)}</span><span>余票 ${x.inventory_left}</span></div><button class="btn primary">选择</button></section>`).join('')}`,'search');bindNav();document.querySelectorAll('[data-rail]').forEach(x=>x.onclick=()=>railSelect(x.dataset.rail))}catch(e){toast(e.message)}}
async function railSelect(id){toast('火车票预订组件尚未就绪，请刷新后重试。')}
function renderRailOrder(){const o=state.railOrder||{},j=o.journey||{};$('#app').innerHTML=shell(`<h1 class="screen-title">火车票订单</h1>${paymentDeadlineHtml(o)}<section class="card"><div class="kv"><span>状态</span><b>${consumerLabel(o.status)}</b></div><div class="kv"><span>车次</span><b>${safe(j.train_no)}</b></div><div class="kv"><span>席别</span><span>${safe(j.seat_class)}</span></div><div class="kv"><span>预订号</span><span>${safe(o.booking_reference)}</span></div><div class="kv"><span>人数 / 含税总价</span><span>${o.passenger_count||0} 人 · ${money(o.total_amount_minor,o.currency)}</span></div><p class="muted">隔离测试订单，不能用于实际乘车。</p></section><section class="card"><button class="btn ghost" id="rchg" ${o.status!=='TICKETED'?'disabled':''}>改签</button><button class="btn danger" id="rref" ${!['TICKETED','REFUND_PENDING'].includes(o.status)?'disabled':''}>${o.status==='REFUND_PENDING'?'继续核对原退款':'退票'}</button>${o.status==='CHANGE_PENDING'?'<button class="btn ghost" id="rresume">继续原改签申请</button>':''}${o.status==='PAYMENT_PENDING'?'<button class="btn danger" id="rcancelunpaid">取消未支付订单</button>':''}<button class="btn ghost" id="rtrips">GO Trips</button></section><section class="card"><h3>证据链</h3>${evHtml(o.evidence)}</section>`,'trips');bindNav();$('#rchg').onclick=railChange;$('#rref').onclick=railRefund;$('#rtrips').onclick=showUnifiedTrips;if($('#rcancelunpaid'))$('#rcancelunpaid').onclick=()=>cancelUnpaidVertical('RAIL');if($('#rresume'))$('#rresume').onclick=railResumeChange}
async function railResumeChange(){const o=state.railOrder,q=(o.change_quotes||[]).find(x=>x.status==='PREPARING');if(!q){toast('正在核对原改签申请，请稍后刷新。');return}uxConfirm({title:'继续原改签申请',description:'将继续处理已经提交的日期、席别和补款方案。',confirmLabel:'继续核对',onConfirm:async()=>{try{await api(`/v1/rail/orders/${encodeURIComponent(o.order_id)}/execute-change/${encodeURIComponent(q.quote_id)}`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()}})}finally{await railReload()}}})}
async function railReload(){state.railOrder=await api(`/v1/rail/orders/${state.railOrder.order_id}`);renderRailOrder()}
function railChange(){uxSheet({title:'铁路改签',fields:[{id:'newTravelDate',label:'新出发日期',type:'date'}],confirmLabel:'查看改签费用',onConfirm:async v=>{const q=await api(`/v1/rail/orders/${state.railOrder.order_id}/change-quote`,{method:'POST',body:JSON.stringify({new_travel_date:v.newTravelDate,new_seat_class:state.railOrder.journey?.seat_class})});uxConfirm({title:'确认铁路改签',summary:`<div class="kv"><span>改签费用</span><b>${money(q.total_due_minor,q.currency)}</b></div>`,confirmLabel:'确认改签',onConfirm:async()=>{try{await api(`/v1/rail/orders/${state.railOrder.order_id}/execute-change/${q.quote_id}`,{method:'POST'})}finally{await railReload()}}})}})}
async function submitVerticalRefund(vertical,orderId){
 const group=vertical==='RAIL'?'rail':'attractions';
 try{return await api(`/v1/${group}/orders/${encodeURIComponent(orderId)}/refund`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()}})}
 catch(e){if(/REFUND_ALREADY_PROCESSING|REFUND_LEASE_LOST/.test(e.message))throw new Error('原退款正在核对，请稍后刷新订单。');throw e}
 finally{const fresh=await api(`/v1/${group}/orders/${encodeURIComponent(orderId)}`);if(vertical==='RAIL'){state.railOrder=fresh;renderRailOrder()}else{state.attractionOrder=fresh;renderAttractionOrder()}}
}
function resumeVerticalRefund(vertical){
 const o=vertical==='RAIL'?state.railOrder:state.attractionOrder;
 return uxConfirm({title:'继续核对原退款',description:'原申请已受理。我们会继续核对同一笔退款，处理中暂不办理改签或核销。',confirmLabel:'核对退款进度',onConfirm:()=>submitVerticalRefund(vertical,o.order_id)});
}
async function railRefund(){if(state.railOrder?.status==='REFUND_PENDING')return resumeVerticalRefund('RAIL');try{const q=await api(`/v1/rail/orders/${state.railOrder.order_id}/refund-quote`);uxConfirm({title:'申请铁路退款',summary:`<div class="kv"><span>预计退款</span><b>${money(q.refund_amount_minor,q.currency)}</b></div>`,confirmLabel:'确认退款',danger:true,onConfirm:async()=>{await submitVerticalRefund('RAIL',state.railOrder.order_id)}})}catch(e){toast(e.message)}}

