function showMobilitySearch(kind){setVerticalVIMode(true);const rental=kind==='RENTAL';state.screen=rental?'rental':'ride';$('#app').innerHTML=shell(`<section class="go-page-head"><button class="go-back" id="mobBack" aria-label="返回">‹</button><div><span>${rental?'租车':'用车'}</span><h1>${rental?'搜索租车':'搜索接送'}</h1></div></section><section class="go-form-card">${rental?`<div class="field"><label for="m1">取车地点</label><input id="m1" placeholder="东京 / NRT"></div><div class="field"><label for="m2">还车地点</label><input id="m2" placeholder="东京 / NRT"></div><div class="field"><label for="mt1">取车时间</label><input id="mt1" type="datetime-local"></div><div class="field"><label for="mt2">还车时间</label><input id="mt2" type="datetime-local"></div>`:`<div class="field"><label for="m1">上车地点</label><input id="m1" placeholder="上海浦东机场 / PVG"></div><div class="field"><label for="m2">目的地</label><input id="m2" placeholder="上海外滩"></div><div class="field"><label for="mt1">上车时间</label><input id="mt1" type="datetime-local"></div>`}<button class="btn primary" id="mgo">查询</button></section>`,'home');bindNav();if(rental)window.GODateRange?.bind({startId:'mt1',endId:'mt2',allowSameDay:true,kind:'datetime',labels:{title:'选择取车和还车日期',start:'取车',end:'还车'}});$('#mobBack').onclick=showHome;$('#mgo').onclick=()=>mobilitySearch(kind)}
async function mobilitySearch(kind){try{const rental=kind==='RENTAL';let b;if(rental){b={pickup_location:$('#m1').value||'NRT',return_location:$('#m2').value||'NRT',pickup_at:$('#mt1').value,return_at:$('#mt2').value,currency:'CNY'}}else{b={pickup:$('#m1').value||'PVG',dropoff:$('#m2').value||'上海外滩',pickup_at:$('#mt1').value?new Date($('#mt1').value).toISOString():'',currency:'CNY'}};if(!b.pickup_at||rental&&!b.return_at){toast('请填写时间');return}const d=await api(rental?'/v1/mobility/rentals/search':'/v1/mobility/rides/search',{method:'POST',body:JSON.stringify(b)});if(rental){state.rentalCriteria=b;state.rentalSearch=d.items||[]}else{state.rideCriteria=b;state.rideSearch=d.items||[]}const rows=(d.items||[]).map(x=>`<section class="card" data-mob="${x.offer_id}"><div class="row"><h3>${safe(x.vehicle_class)}</h3><b>${money(x.total_amount_minor,x.currency)}</b></div>${rental?`<div class="kv"><span>保险</span><span>${safe(x.insurance?.type)}</span></div><div class="kv"><span>押金</span><span>${money(x.deposit_minor,x.currency)}</span></div>`:`<div class="kv"><span>免费等待</span><span>${x.included_wait_minutes}分钟</span></div>`}<button class="btn primary">选择</button></section>`).join('');$('#app').innerHTML=shell(`<h1 class="screen-title">${rental?'租车':'接送'}方案</h1>${rows}`,'search');bindNav();document.querySelectorAll('[data-mob]').forEach(x=>x.onclick=()=>mobilityBook(kind,x.dataset.mob))}catch(e){toast(e.message)}}
async function mobilityBook(kind,id){try{if(!state.me){showAuth();return}const rental=kind==='RENTAL',b=rental?{...state.rentalCriteria,offer_id:id,drivers:[{name:state.me.display_name||'GO Traveler'}]}:{...state.rideCriteria,offer_id:id,passengers:[{name:state.me.display_name||'GO Traveler'}]};if(!rental){if(!window.GOBooking?.acceptRide)throw Error('接送条款确认暂不可用，请刷新后重试。');const accepted=await window.GOBooking.acceptRide(id);if(!accepted)return;b.cancellation_policy_hash=accepted;}const o=await api(rental?'/v1/mobility/rentals/orders':'/v1/mobility/rides/orders',{method:'POST',body:JSON.stringify(b)});const d=await api(`/v1/mobility/orders/${o.order_id}`);if(rental)state.rentalOrder=d;else state.rideOrder=d;renderMobilityOrder(kind)}catch(e){toast(e.message)}}
function renderMobilityOrder(kind){const rental=kind==='RENTAL',o=rental?state.rentalOrder:state.rideOrder;$('#app').innerHTML=shell(`<h1 class="screen-title">${rental?'租车':'接送'}订单</h1><section class="card"><div class="kv"><span>状态</span><b>${!rental&&o.evidence?.some(e=>e.kind==='CANCELLED_NO_REFUND_DUE')?'已取消，无需退款':consumerLabel(o.status)}</b></div><div class="kv"><span>车型</span><b>${safe(o.vehicle_class)}</b></div>${rental?`<div class="kv"><span>保险</span><span>${safe(o.insurance?.type)}</span></div><div class="kv"><span>押金</span><span>${money(o.deposit_minor,o.currency)}</span></div>`:`<div class="kv"><span>行程</span><span>${safe(o.pickup)} → ${safe(o.dropoff)}</span></div>`}<div class="kv"><span>供应确认</span><span>${safe(o.supplier_reference)}</span></div></section><section class="card"><button class="btn ghost" id="mmod" ${o.status!=='CONFIRMED'?'disabled':''}>修改时间</button><button class="btn ghost" id="mstart" ${o.status!=='CONFIRMED'?'disabled':''}>${rental?'确认取车':'确认上车'}</button><button class="btn ghost" id="mend" ${o.status!=='IN_PROGRESS'?'disabled':''}>${rental?'确认还车':'确认送达'}</button><button class="btn danger" id="mcancel" ${o.status!=='CONFIRMED'||(!rental&&!o.cancellation?.cancellable)?'disabled':''}>取消并退款</button></section><section class="card"><h3>证据链</h3>${evHtml(o.evidence)}</section>`,'trips');bindNav();$('#mmod').onclick=()=>mobilityModify(kind);$('#mstart').onclick=()=>mobilityFulfill(kind,rental?'PICKUP':'START');$('#mend').onclick=()=>mobilityFulfill(kind,rental?'RETURN':'COMPLETE');$('#mcancel').onclick=()=>mobilityCancel(kind)}
async function mobilityReload(kind){const o=kind==='RENTAL'?state.rentalOrder:state.rideOrder;const d=await api(`/v1/mobility/orders/${o.order_id}`);if(kind==='RENTAL')state.rentalOrder=d;else state.rideOrder=d;renderMobilityOrder(kind)}
function mobilityModify(kind){const o=kind==='RENTAL'?state.rentalOrder:state.rideOrder;uxSheet({title:kind==='RENTAL'?'修改取车时间':'修改上车时间',fields:[{id:'newTime',label:'新时间',type:'datetime-local'}],confirmLabel:'确认修改',onConfirm:async v=>{await api(`/v1/mobility/orders/${o.order_id}/modify`,{method:'POST',body:JSON.stringify({new_time:kind==='RIDE'?new Date(v.newTime).toISOString():v.newTime})});await mobilityReload(kind)}})}
async function mobilityFulfill(kind,action){const o=kind==='RENTAL'?state.rentalOrder:state.rideOrder;try{await api(`/v1/mobility/orders/${o.order_id}/fulfillment`,{method:'POST',body:JSON.stringify({action,evidence_reference:`CONSUMER_UI_${action}`})});await mobilityReload(kind)}catch(e){toast(e.message)}}
async function mobilityCancel(kind){const o=kind==='RENTAL'?state.rentalOrder:state.rideOrder;try{const q=await api(`/v1/mobility/orders/${o.order_id}/refund-quote`);uxConfirm({title:kind==='RENTAL'?'取消租车订单':'取消接送订单',summary:`<div class="kv"><span>预计退款</span><b>${money(q.refund_amount_minor,q.currency)}</b></div>`,confirmLabel:'确认取消',danger:true,onConfirm:async()=>{await api(`/v1/mobility/orders/${o.order_id}/refund-confirmed`,{method:'POST',body:JSON.stringify({quote_hash:q.quote_hash,confirmed:true})});await mobilityReload(kind)}})}catch(e){toast(e.message)}}

function showAttractionSearch(){setVerticalVIMode(true);state.screen='attraction';$('#app').innerHTML=shell(`<section class="go-page-head"><button class="go-back" id="attrBack" aria-label="返回">‹</button><div><span>景点玩乐</span><h1>景点门票与体验</h1></div></section><section class="go-form-card"><div class="field"><label for="adest">目的地</label><input id="adest" placeholder="东京"></div><div class="field"><label for="adate">游玩日期</label><input id="adate" type="date"></div><button class="btn primary" id="ago">查询</button></section>`,'home');bindNav();$('#attrBack').onclick=showHome;$('#ago').onclick=attractionSearch}
async function attractionSearch(){try{const b={destination:$('#adest').value||'东京',visit_date:$('#adate').value,currency:'CNY'};if(!b.visit_date){toast('请选择日期');return}state.attractionCriteria=b;const d=await api('/v1/attractions/search',{method:'POST',body:JSON.stringify(b)});state.attractionSearch=d.items||[];$('#app').innerHTML=shell(`<h1 class="screen-title">门票与体验</h1>${state.attractionSearch.map(x=>`<section class="card" data-attr="${x.offer_id}"><div class="row"><h3>${safe(x.product_name)}</h3><b>${money(x.total_amount_minor,x.currency)} / 张</b></div><div class="kv"><span>场次</span><span>${safe(x.session_time)}</span></div><div class="kv"><span>库存</span><span>${x.inventory_units}</span></div><div class="kv"><span>凭证</span><span>${consumerLabel(x.voucher_type)}</span></div><button class="btn primary">选择</button></section>`).join('')}`,'search');bindNav();document.querySelectorAll('[data-attr]').forEach(x=>x.onclick=()=>attractionBook(x.dataset.attr))}catch(e){toast(e.message)}}
async function attractionBook(id){toast('门票预订组件尚未就绪，请刷新后重试。')}
function renderAttractionOrder(){const o=state.attractionOrder||{};$('#app').innerHTML=shell(`<h1 class="screen-title">门票 / 体验订单</h1>${paymentDeadlineHtml(o)}<section class="card"><div class="kv"><span>状态</span><b>${consumerLabel(o.status)}</b></div><div class="kv"><span>产品</span><b>${safe(o.product_name)}</b></div><div class="kv"><span>日期 / 场次</span><span>${safe(o.visit_date)} ${safe(o.session_time,'')}</span></div><div class="kv"><span>人数 / 含税总价</span><span>${o.quantity||0} 人 · ${money(o.total_amount_minor,o.currency)}</span></div><div class="kv"><span>核销凭证</span><b>${safe(o.voucher_code)}</b></div></section><section class="card"><button class="btn ghost" id="achg" ${o.status!=='CONFIRMED'?'disabled':''}>改期</button><button class="btn ghost" id="ared" ${o.status!=='CONFIRMED'?'disabled':''}>确认核销</button><button class="btn danger" id="aref" ${!['CONFIRMED','REFUND_PENDING'].includes(o.status)?'disabled':''}>${o.status==='REFUND_PENDING'?'继续核对原退款':'退款'}</button>${o.status==='PAYMENT_PENDING'?'<button class="btn danger" id="acancelunpaid">取消未支付订单</button>':''}</section><section class="card"><h3>证据链</h3>${evHtml(o.evidence)}</section>`,'trips');bindNav();$('#achg').onclick=attractionChange;$('#ared').onclick=attractionRedeem;$('#aref').onclick=attractionRefund;if($('#acancelunpaid'))$('#acancelunpaid').onclick=()=>cancelUnpaidVertical('ATTRACTION')}
async function attractionReload(){state.attractionOrder=await api(`/v1/attractions/orders/${state.attractionOrder.order_id}`);renderAttractionOrder()}
function attractionChange(){uxSheet({title:'修改游玩日期',fields:[{id:'newVisitDate',label:'新游玩日期',type:'date'}],confirmLabel:'查看改期方案',onConfirm:async v=>{const q=await api(`/v1/attractions/orders/${state.attractionOrder.order_id}/change-quote`,{method:'POST',body:JSON.stringify({new_visit_date:v.newVisitDate})});uxConfirm({title:'确认改期',description:'请确认新的日期与当前规则。',confirmLabel:'确认改期',onConfirm:async()=>{await api(`/v1/attractions/orders/${state.attractionOrder.order_id}/execute-change/${q.quote_id}`,{method:'POST'});await attractionReload()}})}})}
