async function attractionRefund(){if(state.attractionOrder?.status==='REFUND_PENDING')return resumeVerticalRefund('ATTRACTION');try{const q=await api(`/v1/attractions/orders/${state.attractionOrder.order_id}/refund-quote`);if(!q.refundable){toast('该产品不可退款');return}uxConfirm({title:'申请门票退款',summary:`<div class="kv"><span>预计退款</span><b>${money(q.refund_amount_minor,q.currency)}</b></div>`,confirmLabel:'确认退款',danger:true,onConfirm:async()=>{await submitVerticalRefund('ATTRACTION',state.attractionOrder.order_id)}})}catch(e){toast(e.message)}}

bootstrapConsumer().finally(()=>{if(!state.me && window.location.hash==='#register')showConsumerRegister();else showHome()});

function cancelUnpaidVertical(vertical){
 const o=vertical==='RAIL'?state.railOrder:state.attractionOrder;
 if(!o||o.status!=='PAYMENT_PENDING')return;
 const group=vertical==='RAIL'?'rail':'attractions';
 return uxConfirm({title:'取消未支付订单',description:'取消后将释放当前预留名额。如已开始支付，请先核对支付结果。',confirmLabel:'确认取消',danger:true,onConfirm:async()=>{
  try{await api(`/v1/${group}/orders/${encodeURIComponent(o.order_id)}/cancel-unpaid`,{method:'POST'})}
  finally{if(vertical==='RAIL')await railReload();else await attractionReload()}
 }});
}

function paymentDeadlineText(o){
 if(o?.unpaid_reservation_state==='EXPIRED')return '付款期限已到，未支付订单已取消，占位已释放。需要出行可重新选择。';
 if(o?.unpaid_reservation_state==='PAYMENT_STARTED')return '支付已开始，占位继续保留；处理结果未明时，请继续核对原支付。';
 if(o?.unpaid_reservation_state!=='OPEN'||o.status!=='PAYMENT_PENDING'||!Number.isSafeInteger(o.payment_deadline_ms)||o.payment_deadline_ms<=0||o.payment_deadline_ms>8640000000000000)return '';
 return `请在 ${new Date(o.payment_deadline_ms).toISOString().replace('T',' ').replace('.000Z',' UTC')} 前开始支付。逾期且未开始支付的订单将取消并释放占位。`;
}
function paymentDeadlineHtml(o){const text=paymentDeadlineText(o);return text?`<p class="muted" role="status">${safe(text)}</p>`:''}
